-- ============================================================================
-- FASTAPI-TEXT2SQL-305: bank clean-up (two assertions, and the filmographies)
-- ============================================================================
--
-- Written 2026-10-01, with the prompt change of the same commit (documentaries are
-- movies, the identifier and documentary rules, the three holes of the drop rule).
-- The bank is shared by the English and the French campaigns, so each fix serves both.
--
-- #2235 "Tommy (1975)". gpt-6-sol returned the right film (ID_MOVIE 11326) with
-- RELEASE_YEAR BETWEEN CAST(1975 AS SIGNED) - 1 AND CAST(1975 AS SIGNED) + 1, and the
-- SQL regex only knew the bare forms. The new regex also accepts a CAST(... AS <type>)
-- and a quoted year around 1975, on both bounds; it still rejects a decade or an
-- unwidened year. ' stands for the quote, so no SQL escaping can break it.
--
-- #2498 "What is Criterion spine number 105?". The assertion named ID_CONTENT, the
-- column of the movies + series UNION gpt-4o wrote; gpt-6-sol answered from
-- T_WC_T2S_MOVIE alone (FR run), which has no ID_CONTENT. ID_MOVIE works for both
-- shapes: the evaluator synthesizes ID_MOVIE from ID_CONTENT + CONTENT_TYPE.
--
-- Guarded on the exact current value: applies once, does nothing on re-run, and
-- withdraws itself if someone edited the value in between. No API call is needed
-- afterwards: rescore with Phase 20 (offline, no token).
--
-- Run: ~/docker/tools/runsqlvaugouindb.sh <this file>
-- ============================================================================

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

SELECT 'A0. Before' AS SECTION;
SELECT ID_T2S_EVALUATION, ASSERTIONS_SQL_QUERY, ASSERTIONS_QUERY_RESULT
FROM T_WC_T2S_EVALUATION
WHERE ID_T2S_EVALUATION IN (2235, 2498)
ORDER BY ID_T2S_EVALUATION;

UPDATE T_WC_T2S_EVALUATION
SET ASSERTIONS_SQL_QUERY = '(?is)(?=.*\\bRELEASE_YEAR\\s+BETWEEN\\s+(?:1974|(?:CAST\\(\\s*)?\\x27?1975\\x27?(?:\\s+AS\\s+\\w+\\s*\\))?\\s*-\\s*1)\\s+AND\\s+(?:1976|(?:CAST\\(\\s*)?\\x27?1975\\x27?(?:\\s+AS\\s+\\w+\\s*\\))?\\s*\\+\\s*1))'
WHERE ID_T2S_EVALUATION = 2235
  AND ASSERTIONS_SQL_QUERY = '(?is)(?=.*\\bRELEASE_YEAR\\s+BETWEEN\\s+(?:1974\\s+AND\\s+1976|1975\\s*-\\s*1\\s+AND\\s+1975\\s*\\+\\s*1))';

UPDATE T_WC_T2S_EVALUATION
SET ASSERTIONS_QUERY_RESULT = 'ID_MOVIE IN (967)'
WHERE ID_T2S_EVALUATION = 2498
  AND ASSERTIONS_QUERY_RESULT = 'ID_CONTENT IN (967)';

SELECT 'A1. After: 2235 carries the CAST form, 2498 reads ID_MOVIE' AS SECTION;
SELECT ID_T2S_EVALUATION, ASSERTIONS_SQL_QUERY, ASSERTIONS_QUERY_RESULT
FROM T_WC_T2S_EVALUATION
WHERE ID_T2S_EVALUATION IN (2235, 2498)
ORDER BY ID_T2S_EVALUATION;

-- ----------------------------------------------------------------------------
-- SECTION B. Filmographies: no documentary expected, at most 20 movies expected.
--
-- Philippe, 2026-10-01. 562 (James Stewart) expected no documentary, 907 (Sharon Tate)
-- expected six; under the rule "a documentary is a movie" a model may list them or not,
-- and their place in the first page of 100 rows depends on the person. A filmography
-- assertion therefore requires only fiction, and only a sample: the 20 best-rated
-- (IMDB_RATING_WEIGHTED) non-documentary movies of the current list, all of them when
-- the list holds 20 or fewer. A documentary in the answer is neither required nor
-- forbidden. The new list is computed here, from the movies table, because only the
-- database knows IS_DOCUMENTARY.
-- Scope: the 49 evaluations whose answer is the movies of one named person, cast or
-- crew, with or without another filter. Left out on purpose: 35 (documentaries by
-- Agnès Varda, which asks for them).
-- Guards: the exact current value (taken from the 2026-09 exports; a row edited since
-- is left alone and shows unchanged in B1), and at least 5 movies left.
-- ----------------------------------------------------------------------------

SELECT 'B0. Before' AS SECTION;
SELECT ID_T2S_EVALUATION, LEFT(QUESTION, 60) AS QUESTION,
       LENGTH(ASSERTIONS_QUERY_RESULT) - LENGTH(REPLACE(ASSERTIONS_QUERY_RESULT, ',', '')) + 1 AS IDS_EXPECTED
FROM T_WC_T2S_EVALUATION
WHERE ID_T2S_EVALUATION IN (8, 10, 26, 51, 56, 58, 64, 70, 88, 92, 95, 108, 112, 335, 480, 483, 484, 490, 505, 506, 553, 562, 563, 564, 565, 568, 585, 593, 634, 693, 702, 731, 768, 809, 812, 850, 870, 878, 879, 905, 907, 919, 925, 975, 984, 1081, 1116, 1126, 1127)
ORDER BY ID_T2S_EVALUATION;

-- #8 What movies did Stanley Kubrick direct?
UPDATE T_WC_T2S_EVALUATION e
JOIN (SELECT CONCAT('ID_MOVIE IN (', GROUP_CONCAT(t.ID_MOVIE ORDER BY t.IMDB_RATING_WEIGHTED DESC, t.ID_MOVIE SEPARATOR ', '), ')') AS A, COUNT(*) AS N
      FROM (SELECT ID_MOVIE, IMDB_RATING_WEIGHTED FROM T_WC_T2S_MOVIE
            WHERE ID_MOVIE IN (975, 694, 62, 935, 600, 185, 3175, 247, 967, 802, 345, 10056, 10165) AND COALESCE(IS_DOCUMENTARY, 0) = 0
            ORDER BY IMDB_RATING_WEIGHTED DESC, ID_MOVIE LIMIT 20) t) x
SET e.ASSERTIONS_QUERY_RESULT = x.A
WHERE e.ID_T2S_EVALUATION = 8 AND e.ASSERTIONS_QUERY_RESULT = 'ID_MOVIE IN (975, 694, 62, 935, 600, 185, 3175, 247, 967, 802, 345, 10056, 10165)' AND x.N >= 5;

